        if isinstance(inst, dict):
            for k in ("demands", "demand", "loads"):
                if k in inst:
                    return inst[k]
        return None

    def get_customers(inst, depot, coords, demands):
        ids = []
        if isinstance(inst, dict):
            for k in ("customers", "nodes"):
                if k in inst and isinstance(inst[k], (list, tuple)):
                    ids = list(inst[k])
                    break
        if not ids:
            if isinstance(coords, dict):
                ids = list(coords.keys())
            elif isinstance(coords, (list, tuple)):
                ids = list(range(len(coords)))
            elif isinstance(demands, dict):
                ids = list(demands.keys())
            elif isinstance(demands, (list, tuple)):
                ids = list(range(len(demands)))
        return [i for i in ids if i != depot]

    def demand_of(node, demands):
        if demands is None:
            return 1
        if isinstance(demands, dict):
            return demands.get(node, 1)
        try:
            return demands[node]
        except Exception:
            return 1

    def coord_of(node, coords):
        if coords is None:
            return None
        if isinstance(coords, dict):
            return coords.get(node, None)
        try:
            return coords[node]
        except Exception:
            return None

    def dist(a, b, coords):
        pa = coord_of(a, coords)
        pb = coord_of(b, coords)
        if pa is None or pb is None:
            return 0.0
        ax, ay = pa[0], pa[1]
        bx, by = pb[0], pb[1]
        dx = ax - bx
        dy = ay - by
        return (dx * dx + dy * dy) ** 0.5

    def route_load(route, demands):
        s = 0
        for n in route:
            s += demand_of(n, demands)
        return s

    def route_cost(route, depot, coords):
        if not route:
            return 0.0
        c = dist(depot, route[0], coords) + dist(route[-1], depot, coords)
        for i in range(len(route) - 1):
            c += dist(route[i], route[i + 1], coords)
        return c

    depot = get_depot(instance)
    capacity = get_capacity(instance)
    coords = get_coords(instance)
    demands = get_demands(instance)
    customers = get_customers(instance, depot, coords, demands)

    if capacity is None:
        total = 0
        for c in customers:
            total += demand_of(c, demands)
        capacity = max(1, total)

    if not customers:
        return []

    # Deterministic ordering seed: sweep if coordinates exist, otherwise by demand/id.
    if coords is not None:
        cx = 0.0
        cy = 0.0
        depc = coord_of(depot, coords)
        if depc is not None:
            cx, cy = depc[0], depc[1]

        def sweep_key(c):
            p = coord_of(c, coords)
            if p is None:
                return (10**9, 10**9, demand_of(c, demands), c)
            dx = p[0] - cx
            dy = p[1] - cy
            ang = dy if dx == 0 and dy == 0 else (dy / (abs(dx) + abs(dy) + 1e-12))
            rad = dx * dx + dy * dy
            return (ang, rad, demand_of(c, demands), c)

        ordered = sorted(customers, key=sweep_key)
    else:
        ordered = sorted(customers, key=lambda c: (demand_of(c, demands), c))

    # Initial feasible packing by sweep order.
    routes = []
    current = []
    load = 0
    for c in ordered:
        d = demand_of(c, demands)
        if current and load + d > capacity:
            routes.append(current)
            current = [c]
            load = d
        else:
            current.append(c)
            load += d
    if current:
        routes.append(current)

    # If any route still exceeds capacity, split greedily.
    fixed = []
    for r in routes:
        tmp = []
        ld = 0
        for c in r:
            d = demand_of(c, demands)
            if tmp and ld + d > capacity:
                fixed.append(tmp)
                tmp = [c]
                ld = d
            else:
                tmp.append(c)
                ld += d
        if tmp:
            fixed.append(tmp)
    routes = fixed

    # Local improvement: reverse if beneficial, then 2-opt within routes.
    if coords is not None:
        improved = True
        while improved:
            improved = False
            for ri in range(len(routes)):
                r = routes[ri]
                if len(r) < 3:
                    continue
                best_gain = 0.0
                best_i = None
                best_j = None
                base = route_cost(r, depot, coords)
                for i in range(len(r) - 2):
                    for j in range(i + 2, len(r)):
                        cand = r[:i + 1] + list(reversed(r[i + 1:j + 1])) + r[j + 1:]
                        new_cost = route_cost(cand, depot, coords)
                        gain = base - new_cost
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best_i = i
                            best_j = j
                if best_i is not None:
                    routes[ri] = r[:best_i + 1] + list(reversed(r[best_i + 1:best_j + 1])) + r[best_j + 1:]
                    improved = True

    # Inter-route relocate and swap, capacity-aware.
    changed = True
    while changed:
        changed = False
        # relocate single customer to another route if it reduces cost
        best_move = None
        best_delta = 0.0
        for i in range(len(routes)):
            for pos in range(len(routes[i])):
                c = routes[i][pos]
                dc = demand_of(c, demands)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    if route_load(routes[j], demands) + dc > capacity:
                        continue
                    r1 = routes[i]
                    r2 = routes[j]
                    before = route_cost(r1, depot, coords) + route_cost(r2, depot, coords)
                    nr1 = r1[:pos] + r1[pos + 1:]
                    if not nr1:
                        continue
                    for ins in range(len(r2) + 1):
                        nr2 = r2[:ins] + [c] + r2[ins:]
                        after = route_cost(nr1, depot, coords) + route_cost(nr2, depot, coords)
                        delta = before - after
                        if delta > best_delta + 1e-12:
                            best_delta = delta
                            best_move = (i, j, pos, ins)
        if best_move is not None:
            i, j, pos, ins = best_move
            c = routes[i][pos]
            routes[i].pop(pos)
            routes[j].insert(ins, c)
            if not routes[i]:
                routes.pop(i)
            changed = True
            continue

        # swap between routes if it improves cost and preserves capacity
        best_swap = None
        best_delta = 0.0
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                r1 = routes[i]
                r2 = routes[j]
                l1 = route_load(r1, demands)
                l2 = route_load(r2, demands)
                for a in range(len(r1)):
                    ca = r1[a]
                    da = demand_of(ca, demands)
                    for b in range(len(r2)):
                        cb = r2[b]
                        db = demand_of(cb, demands)
                        if l1 - da + db > capacity:
                            continue
                        if l2 - db + da > capacity:
                            continue
                        before = route_cost(r1, depot, coords) + route_cost(r2, depot, coords)
                        nr1 = r1[:a] + [cb] + r1[a + 1:]
                        nr2 = r2[:b] + [ca] + r2[b + 1:]
                        after = route_cost(nr1, depot, coords) + route_cost(nr2, depot, coords)
                        delta = before - after
                        if delta > best_delta + 1e-12:
                            best_delta = delta
                            best_swap = (i, j, a, b)
        if best_swap is not None:
            i, j, a, b = best_swap
            routes[i][a], routes[j][b] = routes[j][b], routes[i][a]
            changed = True

    # Final normalization: remove empties and ensure all customers appear once.
    seen = set()
    cleaned = []
    for r in routes:
        nr = []
        for c in r:
            if c == depot:
                continue
            if c not in seen:
                seen.add(c)
                nr.append(c)
        if nr:
            cleaned.append(nr)
    missing = [c for c in customers if c not in seen]
    if missing:
        # Insert missing customers into feasible routes or create new routes.
        for c in missing:
            d = demand_of(c, demands)
            best = None
            best_pos = None
            best_delta = None
            if coords is not None:
                for i in range(len(cleaned)):
                    if route_load(cleaned[i], demands) + d > capacity:
                        continue
                    r = cleaned[i]
                    base = route_cost(r, depot, coords)
                    for pos in range(len(r) + 1):
                        nr = r[:pos] + [c] + r[pos:]
                        delta = route_cost(nr, depot, coords) - base
                        if best_delta is None or delta < best_delta:
                            best_delta = delta
                            best = i
                            best_pos = pos
            if best is not None:
                cleaned[best].insert(best_pos, c)
            else:
                cleaned.append([c])

    return cleaned
